110:function doChangeHoverState(el: ECElement, stateName: DisplayState, hoverStateEnum: 0 | 1 | 2) {
111:    if (el.onHoverStateChange && (el.hoverState || 0) !== hoverStateEnum) {
112:        el.onHoverStateChange(stateName);
113:    }
114:    el.hoverState = hoverStateEnum;
