156:function traverseUpdateState<T>(
157:    el: ExtendedElement,
158:    updater: (this: void, el: Element, commonParam?: T) => void,
159:    commonParam?: T
160:) {
161:    updateElementState(el, updater, commonParam);
162:    el.isGroup && el.traverse(function (child: ExtendedElement) {
163:        updateElementState(child, updater, commonParam);
164:    });
165:}
