167:export function setStatesFlag(el: ECElement, stateName: DisplayState) {
168:    switch (stateName) {
169:        case 'emphasis':
170:            el.hoverState = HOVER_STATE_EMPHASIS;
171:            break;
172:        case 'normal':
173:            el.hoverState = HOVER_STATE_NORMAL;
174:            break;
175:        case 'blur':
176:            el.hoverState = HOVER_STATE_BLUR;
177:            break;
178:        case 'select':
179:            el.selected = true;
180:    }
181:}
