199:function getFromStateStyle(
200:    el: Displayable,
201:    props: (keyof PathStyleProps)[],
202:    toStateName: string,
203:    defaultValue?: PathStyleProps
204:): PathStyleProps {
205:    const style = el.style;
206:    const fromState: PathStyleProps = {};
207:    for (let i = 0; i < props.length; i++) {
208:        const propName = props[i];
209:        const val = style[propName];
210:        (fromState as any)[propName] = val == null ? (defaultValue && defaultValue[propName]) : val;
211:    }
212:    for (let i = 0; i < el.animators.length; i++) {
213:        const animator = el.animators[i];
214:        if (animator.__fromStateTransition
215:            // Don't consider the animation to emphasis state.
216:            && animator.__fromStateTransition.indexOf(toStateName) < 0
217:            && animator.targetName === 'style') {
218:            animator.saveTo(fromState, props);
219:        }
220:    }
221:    return fromState;
222:}
